test_suite:
test('starts idle when promise is null', () => {
  const { result } = renderHook(() => usePromiseState(null));
  expect(result.current.status).toBe('idle');
  expect(result.current.data).toBeNull();
  expect(result.current.error).toBeNull();
});

test('transitions to pending when promise provided', async () => {
  const p = new Promise<string>(() => {});
  const { result } = renderHook(() => usePromiseState(p));
  expect(result.current.status).toBe('pending');
});

test('transitions to fulfilled with data on resolve', async () => {
  const p = Promise.resolve('hello');
  const { result } = renderHook(() => usePromiseState(p));
  await act(async () => { await p; });
  expect(result.current.status).toBe('fulfilled');
  expect(result.current.data).toBe('hello');
});

test('transitions to rejected with error on reject', async () => {
  const err = new Error('oops');
  const p = Promise.reject(err);
  const { result } = renderHook(() => usePromiseState(p));
  await act(async () => { await p.catch(() => {}); });
  expect(result.current.status).toBe('rejected');
  expect(result.current.error).toBe(err);
});

// __hidden__
test('ignores stale promise after new one provided', async () => {
  let resolveFirst!: (v: string) => void;
  const first = new Promise<string>(r => { resolveFirst = r; });
  const second = Promise.resolve('second');
  const { result, rerender } = renderHook(
    ({ p }) => usePromiseState(p),
    { initialProps: { p: first as Promise<string> | null } }
  );
  rerender({ p: second });
  await act(async () => { await second; });
  resolveFirst('first');
  await act(async () => {});
  expect(result.current.data).toBe('second');
});

solution:
import { useState, useEffect } from 'react';

type Status = 'idle' | 'pending' | 'fulfilled' | 'rejected';

interface PromiseState<T> {
  status: Status;
  data: T | null;
  error: Error | null;
}

export function usePromiseState<T>(promise: Promise<T> | null): PromiseState<T> {
  const [state, setState] = useState<PromiseState<T>>({
    status: 'idle',
    data: null,
    error: null,
  });

  useEffect(() => {
    if (!promise) {
      setState({ status: 'idle', data: null, error: null });
      return;
    }
    let cancelled = false;
    setState({ status: 'pending', data: null, error: null });
    promise.then(
      data => { if (!cancelled) setState({ status: 'fulfilled', data, error: null }); },
      err => { if (!cancelled) setState({ status: 'rejected', data: null, error: err instanceof Error ? err : new Error(String(err)) }); }
    );
    return () => { cancelled = true; };
  }, [promise]);

  return state;
}
